export async function resetDelivery(h: Host): Promise<void> { for (const n of Object.keys((await cfgOf(h)).adapters)) { const k = `deliver:${n}`, st = await h.store.get(k); if (st) await h.store.set(k, { ...(st as object), init: false }) } }
