    return { lines: [`+ .cadre/config.json: sync.${name}.mapping =`, ...Object.entries(m).filter(([, v]) => v && Object.keys(v as object).length).map(([k, v]) => `    ${k}: ${canon(v)}`)], apply: async () => { d.mapping = m; await set(x => { x.mapping = m }) } }
