// Decision card (ADR 0008): the ONE renderer of any Decision (core/decide). A framed box: title, the record's lines, its options as Buttons (key = hotkey);
// "n of m" with n/p when several are pending. Driven only by the record: a new kind of decision needs no UI code. The rest of the pane is drawn dim and key-less below.
import { type Acts, type Decision, type Line, type View, L, S, T, attention, cols, gl, padL, tg, col } from './model'
import { sheet } from './sheet'
import { wrap } from './sheet'

export const decisions = (v: View): Decision[] => v.b.decisions ?? []
export const cur = (v: View): number => Math.min(Math.max(0, Number(v.ui.di ?? 0)), Math.max(0, decisions(v).length - 1))
export const defaultTab = (v: View) => (decisions(v).length ? 'card' : 'epic')
const dim = (ls: Line[]): Line[] => ls.map(l => l.map(s => ({ t: s.t, c: s.c, d: true })))   // no keys: only the card's buttons answer
export function card(v: View, w: number, a: Acts): Line[] {
  const all = decisions(v), i = cur(v), d = all[i], c = v.c, n = Math.max(20, Math.min(w, 110) - 4), fr = (l: Line): Line => [S(T(c, '║ ')), ...padL(l, n), S(T(c, ' ║'))]
  const bar = (l: string, m: string, r: string) => L(T(c, `${l}${m.repeat(n + 2)}${r}`))
  const tag = attention(v).find(x => x.d === d)?.tag ?? 'attn', live = v.t === null
  const nav: Line = all.length > 1 ? [S(`${i + 1} of ${all.length}   `), S('prev', undefined, { k: 'p', hk: 'p', p: () => a.step('dec', -1) }), S('  '), S('next', undefined, { k: 'n', hk: 'n', p: () => a.step('dec', 1) })] : []
  const btns: Line = live ? d.options.flatMap((o, j) => [...(j ? [S('   ')] : []), S(o.label, 'suggestion', { k: o.key, hk: o.key, b: true, p: () => (o.fill ? a.fill(o.fill) : a.press(d.id, o.key, d.hash)) })]) : [S('(read-only in replay)')]
  // fields (ADR 0009): one Input per field, prefilled; typed values live in cadre.ui `fields`; Enter in a field submits the first option (Tab moves between fields)
  const typed = ((v.ui.fields as Record<string, Record<string, string>> | undefined) ?? {})[d.id] ?? {}, go = d.options[0]
  const fs: Line[] = (d.fields ?? []).map((f, j) => { const val = typed[f.key] ?? f.value ?? ''
    return live ? [S(`${f.label}: ${val}`, undefined, { k: `f:${d.id}:${f.key}`, il: f.label, iv: val, ...(j ? {} : { af: true as const }), chg: x => a.input?.(d.id, f.key, x), inp: x => { a.input?.(d.id, f.key, x); if (go) a.press(d.id, go.key, d.hash) } })] : [S(`${f.label}: ${val}`)] })
  const body: Line[] = [[S(`${tg(tag)} ${gl(c, tag)} ${d.title}`.slice(0, n), col(tag), { b: true })], L(''), ...d.lines.map(x => (x.length > n && /^\s*(sudo )?sh \S+\.sh$/.test(x) ? x.replace(/(sudo )?sh /, '') : x)).flatMap(x => wrap(x, n, '  ').map(y => L(y))),
    ...(fs.length ? [L(''), ...fs, ...(d.error ? [[S(`! ${d.error}`, 'error')]] : []), L('Tab: next field · Enter: submit · Esc: back to the buttons', 'inactive')] : []), L(''), ...(nav.length ? [nav] : []), btns]
  const under = d.tab === 'plan' ? sheet(v, w, a) : cols(v.b.tasks).flat().map(t => L(`${t.id} ${t.title}`))
  return [bar('╔', '═', '╗'), ...body.map(fr), bar('╚', '═', '╝'), ...dim(under)]
}

files.ui/timeline.ts:
// Timeline swimlanes as ONE Raster (UI-DESIGN 6.2, 8; UI-21): spans from agent.bound/unbound, outages from sync.state_changed, markers by notification level, the cursor.
// Cursor moves repaint through $.ui.blit (no tree re-render); in replay the cursor is the moment and later spans draw ╌.
import type { CadreEvent, Host } from '../types'
import { type Cfg, type View, T, ago, t0 } from './model'
import { levelOf } from './notify'

const FG: Record<string, number> = { '█': 0x61afef, '▒': 0xc678dd, '░': 0xe5c07b, '╌': 0x5c6370, '┃': 0xe5c07b, '▼': 0xe5c07b, '.': 0x5c6370, o: 0x98c379, '*': 0xe5c07b, '!': 0xe06c75 }
const DEF = 0x01000000, NAME: Record<string, string> = { human: 'hum', main: 'mai', tester: 'tst', 'worker 1': 'w1', 'worker 2': 'w2', reviewer: 'rev', explorer: 'exp', sync: 'syn' }

export type Span = { lane: string; from: number; to: number; ch: string; task?: string; open?: boolean }
// agent spans and sync outages folded from the ring; workers take the first free lane, tasks in plan order (so a task keeps its lane across resumes)
export function spansOf(v: View): { spans: Span[]; workers: number } {
  const open = new Map<string, Omit<Span, 'to'>>(), spans: Span[] = []
  for (const e of v.ring) {
    if (e.type === 'agent.bound') open.set(String(e.data.agentId), { lane: String(e.data.role), from: e.at, ch: e.data.role === 'reviewer' ? '▒' : '█', task: String(e.data.taskId) })
    else if (e.type === 'agent.unbound') { const o = open.get(String(e.data.agentId)); if (o) { spans.push({ ...o, to: e.at }); open.delete(String(e.data.agentId)) } }
    else if (e.type === 'sync.state_changed') {
      const k = `sync:${e.data.target}`, o = open.get(k)
      if (e.data.state !== 'ok' && !o) open.set(k, { lane: 'sync', from: e.at, ch: '░' })
      else if (e.data.state === 'ok' && o) { spans.push({ ...o, to: e.at }); open.delete(k) }
    }
  }
  for (const o of open.values()) spans.push({ ...o, to: Math.max(v.now, v.t ?? 0), open: true })
  const order = v.b.tasks.map(t => t.id), lanes: Span[][] = []
  for (const s of spans.filter(x => x.lane === 'worker').sort((x, y) => order.indexOf(x.task!) - order.indexOf(y.task!) || x.from - y.from)) {
    let i = lanes.findIndex(l => l.every(x => x.to <= s.from || x.from >= s.to)); if (i < 0) i = lanes.push([]) - 1
    lanes[i].push(s); s.lane = `worker ${i + 1}`
  }
  return { spans, workers: Math.max(1, lanes.length) }
}
// the lane an agent-made event belongs to: the span of its task that ends at it, else one containing it
export const laneOf = (spans: Span[], e: CadreEvent) => { const s = spans.filter(x => x.task && x.task === e.taskId); return (s.find(x => x.to === e.at) ?? s.find(x => x.from <= e.at && e.at < x.to))?.lane }
export const abbr = (lane: string) => NAME[lane] ?? lane

export type Tl = { head: string; rows: string[]; cols: number; mpc: number }
export function timeline(v: View, w: number): Tl {
  const wide = w >= 116, lab = wide ? 10 : 4, n = w - lab - 1, base = t0(v), cur = v.t ?? v.now, end = Math.max(v.now, cur, ...v.ring.map(e => e.at))
  const mpc = Math.max(1, Math.ceil((((end - base) / 60000) + 1) / n)), colOf = (t: number) => Math.min(n - 1, Math.max(0, Math.floor((t - base) / 60000 / mpc))), cc = colOf(cur)
  const { spans, workers } = spansOf(v)
  const lanes = ['human', 'main', 'tester', ...Array.from({ length: workers }, (_, i) => `worker ${i + 1}`), 'reviewer', 'explorer', 'sync']
  const rows = lanes.map(() => Array(n).fill(' ') as string[])
  const put = (lane: string, x: number, ch: string) => { const r = rows[lanes.indexOf(lane)]; if (r) r[x] = ch }
  for (const s of spans) for (let x = colOf(s.from), e = s.open ? colOf(s.to) + 1 : Math.min(n, Math.ceil((s.to - base) / 60000 / mpc)); x < e; x++) put(s.lane, x, x > cc ? '╌' : s.ch)   // [from, to) in minutes: the verdict mark sits on `to`
  for (const e of v.ring) { const l = levelOf(e); const al = e.actor === 'mod' ? laneOf(spans, e) : undefined; if (l && e.at <= cur && (al || e.actor !== 'mod' || l > 1)) put(al ?? (e.actor === 'human' || e.needsHuman ? 'human' : e.actor === 'mod' ? 'main' : e.actor), colOf(e.at), '.o*!'[l]) }
  const axis = Array(n).fill(' ') as string[], step = wide ? 10 : 20
  for (let m = 0; m + step <= n * mpc; m += step) [...`${m}m`].forEach((ch, i) => { if (m / mpc + i < n) axis[m / mpc + i] = ch })
  for (const r of rows) if (r[cc] === ' ') r[cc] = '┃'
  axis[cc] = '▼'
  const line = (name: string, r: string[]) => (wide ? name.padEnd(lab) : (NAME[name] ?? name).padEnd(lab)) + r.join('')
  const mode = v.t === null ? '[LIVE]' : `[REPLAY t-${ago(v.now - v.t).slice(0, -1)}m]`
  const head = wide ? `TIMELINE  ${mode} now ${ago(cur - base)} · █ work ▒ review ░ offline · . silent o band * toast ! notify · t: hide` : `TIMELINE  ${mpc} min/col · ░ offline · ┃ ${ago(cur - base)}`
  return { head: T(v.c, head), rows: [' '.repeat(lab) + axis.join(''), ...lanes.map((l, i) => line(l, rows[i]))].map(r => r.padEnd(w)), cols: w, mpc }
}
export function cells(tl: Tl, c: Cfg): string {
  const u = new Uint32Array(tl.cols * tl.rows.length * 3)
  tl.rows.forEach((r, y) => [...r].forEach((ch, x) => { const i = (y * tl.cols + x) * 3; u[i] = T(c, ch).codePointAt(0)!; u[i + 1] = FG[ch] ?? DEF; u[i + 2] = DEF }))
  const b = new Uint8Array(u.buffer)
  return (b as { toBase64?: () => string }).toBase64?.() ?? btoa(Array.from(b, x => String.fromCharCode(x)).join(''))
}
// cursor-only repaint (live clock tick, replay keys): same size, no re-render
export async function blit(h: Host, v: View, w: number): Promise<void> {
  const tl = timeline(v, w)
  await h.ops?.blit({ requestId: 'cadre', key: 'tl', cells: cells(tl, v.c) })
}

files.ui/notify.ts:
// Notification policy (UI-DESIGN 4): level from kind + severity + needsHuman (never stored), dedupe by key, <=1 toast / 8 s with merging, OS notify <=1/item and <=3 / 15 min,
// escalation after ui.escalateAfterMs unless acked, status line = top attention item only. State lives in the cadre.ui atom; side effects run after the CAS settles.
import type { CadreEvent, Host } from '../types'
import { CFG, attention, read } from './model'

export type Level = 0 | 1 | 2 | 3   // silent . · band o · toast * · notify !
export function levelOf(e: CadreEvent): Level {
  const d = e.data, st = String(d.state ?? d.to ?? '')
  switch (e.type) {
    case 'approval.pending': case 'flag.raised': return 3
    case 'task.transitioned': return st === 'blocked' ? 3 : st === 'done' || d.from === 'review' && st === 'active' ? 1 : e.severity === 'crit' ? 2 : 0
    case 'check.ran': return 1
    case 'sync.state_changed': return st === 'ok' && !d.conflicts ? 1 : 2
    case 'drive.status': return st === 'paused' || st === 'finished' ? 3 : 0
    case 'agent.unbound': return d.reason === 'stale' ? 1 : 0
    case 'init.stage': return st === 'proposed' ? 2 : 1   // done / Claude working: in the log, no toast
    case 'cost.updated': return d.threshold ? 2 : 0
    default: return e.needsHuman ? 3 : e.severity === 'crit' ? 2 : 0
  }
}
// matrix text (no secrets, D7) + dedupe key; undefined = no toast
export function textOf(e: CadreEvent): { text: string; key: string } | undefined {
  const d = e.data, id = e.taskId ?? String(d.taskId ?? ''), st = String(d.state ?? d.to ?? '')
  switch (e.type) {
    case 'approval.pending': return { text: `Plan ${d.planId} ready for approval · press 1`, key: `approve:${d.planId}:${d.rev ?? ''}` }
    case 'task.transitioned': return st === 'blocked' ? { text: `${id} blocked: needs an answer`, key: `q:${id}:${d.hash ?? ''}` } : undefined
    case 'flag.raised': return { text: `${id} flagged ${d.flag} · press 1`, key: `flag:${id}:${d.flag}` }
    case 'sync.state_changed': return st === 'ok' ? { text: `${d.target} reconnected${d.conflicts ? ` · ${d.conflicts} conflict` : ''}`, key: `off:${d.target}` } : { text: `${d.target} ${st} · retrying`, key: `off:${d.target}` }
    case 'drive.status': return st === 'paused' || st === 'finished' ? { text: st === 'paused' ? `Drive paused${d.reason ? `: ${d.reason}` : ''}` : 'Epic landed on dev ✓', key: `drive:${st}` } : undefined
    case 'cost.updated': return d.threshold ? { text: `Drive at ${d.threshold}% of token budget`, key: `cost:${d.threshold}` } : undefined
    case 'init.stage': return st === 'proposed' ? { text: 'Init diff ready · /cadre open init', key: `init:${d.stage}` } : undefined
    default: return undefined
  }
}
const CLOSE: Partial<Record<CadreEvent['type'], (e: CadreEvent) => string>> = { 'flag.resolved': e => `flag:${e.taskId}:${e.data.flag}`, 'sync.state_changed': e => (e.data.state === 'ok' ? `off:${e.data.target}` : '') }

export const ack = (h: Host) => h.now().then(n => h.ui.update(u => ({ ...u, ack: n })))   // composer submit, any /cadre, a cadre press, pane focus

async function toast(h: Host, text: string, now: number): Promise<void> {
  let direct = false, first = false, wait = 0
  await h.ui.update(u => {
    const q = (u.q as string[] | undefined) ?? [], dt = now - ((u.lt as number | undefined) ?? -1e9)
    direct = dt >= 8000 && !q.length; first = !direct && !q.length; wait = Math.max(0, 8000 - dt)
    return direct ? { ...u, lt: now } : { ...u, q: [...q, text] }
  })
  if (direct) h.ops?.toast(text, { timeoutMs: 6000 })
  else if (first) h.ops?.after(wait, async () => {   // coalesce what arrived inside the window
    let q: string[] = []
    await h.ui.update(u => { q = (u.q as string[]) ?? []; return { ...u, q: [], lt: now + wait } })
    if (q.length) h.ops?.toast(q.length === 1 ? q[0] : `${q.length} updates: ${q.join(' · ')}`, { timeoutMs: 6000 })
  })
}
async function notify(h: Host, key: string, text: string, now: number): Promise<void> {
  const cfg = { ...CFG, ...((await h.ui.read()).cfg as object) }
  if (cfg.notify === 'off' || !h.ops || await h.ops.focused()) return
  let ok = false
  await h.ui.update(u => {
    const nt = ((u.nt as number[] | undefined) ?? []).filter(x => now - x < 900_000), sent = (u.nf as Record<string, number> | undefined) ?? {}
    ok = !(key in sent) && nt.length < 3
    return ok ? { ...u, nt: [...nt, now], nf: { ...sent, [key]: now } } : u
  })
  if (ok && !(await h.ops.notify(text, { title: 'cadre' })).isSent) h.ops.toast(text, { timeoutMs: 6000 })
}
// status line: the top attention item, cleared when none (never the command, so never a code)
export async function syncStatus(h: Host): Promise<void> { const top = attention(await read(h))[0]; h.ops?.status(top ? `${top.text} · press 1` : undefined) }

// subscribed to core/events: one call per emitted event
export async function onEvent(h: Host, e: CadreEvent): Promise<void> {
  const k = CLOSE[e.type]?.(e), lv = levelOf(e), t = textOf(e)
  if (k) await h.ui.update(u => { const { [k]: _x, ...rest } = (u.open as Record<string, number> | undefined) ?? {}; return { ...u, open: rest } })
  if (lv >= 2 && t) {
    let fresh = false
    await h.ui.update(u => { const o = (u.open as Record<string, number> | undefined) ?? {}; fresh = !(t.key in o); return fresh ? { ...u, open: { ...o, [t.key]: e.at } } : u })
    if (fresh) {
      await toast(h, t.text, e.at)
      if (lv === 3) {
        if (e.type === 'drive.status') await notify(h, t.key, t.text, e.at)   // drive paused/finished: immediately
        else h.ops?.after(((await h.ui.read()).cfg as { escalateAfterMs?: number } | undefined)?.escalateAfterMs ?? CFG.escalateAfterMs, async () => {
          const u = await h.ui.read()
          if (t.key in ((u.open as object) ?? {}) && ((u.ack as number | undefined) ?? 0) < e.at) await notify(h, t.key, t.text, await h.now())
        })
      }
    }
  }
  await syncStatus(h)
}

files.core/discover.ts:
// Stage 4 discovery (DESIGN 10.2): brief for the explorer, report{discovery} parsing, jailed runs (audit + validate). Pure helpers + h.run; no language logic.
import type { Host } from '../types'
import * as G from './git'

export interface Pkg {
  root: string; setup: string[]; checks: Record<string, string[]>; fetches?: string[]
  tdd?: { paths: string[]; report?: string; stubs?: string[]; skeleton?: string[] }; viewInclude?: string[]
}
export type Verdict = 'pass' | 'red' | 'net' | 'knownRed'
export interface Run { setupOk: boolean; caches: string[]; results: Record<string, Verdict>; junit?: boolean }

export const brief = (): string => `cadre discovery (read-only). Find how this repo is built and tested; CI config wins over prose.
Read: CI config, task runners, manifests, README/CONTRIBUTING, test dirs. Per package answer ONE mcp__cadre__report {role:"explorer", discovery:{packages:[
{root, setup:[argv] (or [] when none), checks:{name:[argv]}, fetches?:[names of checks whose CI step fetches at test time], tdd:{paths:[globs], report?:"/tmp/cadre/<n>.xml" (JUnit), stubs?:[argv], skeleton?:[argv]}, viewInclude?:[paths]}]}, citations:[{path,line}]}.
Every argv cites the file it came from. Commands only; no shell strings. Do not run anything.`

const isArgv = (v: unknown): v is string[] => Array.isArray(v) && v.length > 0 && v.every(x => typeof x === 'string' && x !== '')
export function parse(r: any): Pkg[] | string {
  const ps = r?.discovery?.packages
  if (!Array.isArray(ps) || !ps.length) return 'discovery.packages: expected [{root, setup, checks, tdd}], e.g. {"root":".","setup":["npm","ci"],"checks":{"test":["npm","test"]},"tdd":{"paths":["test/**"]}}'
  if (!Array.isArray(r.citations) || !r.citations.length) return 'citations: expected [{path,line}] naming the files the argv came from'
  for (const [i, p] of ps.entries()) {
    const at = `discovery.packages[${i}]`
    if (typeof p?.root !== 'string' || p.root.startsWith('/') || p.root.split('/').includes('..')) return `${at}.root: expected a repo-relative path like "." or "packages/api"`
    if (p.setup !== undefined && !(Array.isArray(p.setup) && !p.setup.length) && !isArgv(p.setup)) return `${at}.setup: expected an argv array like ["npm","ci"], or [] when the repo has no setup step`
    const cs = Object.entries(p.checks ?? {}); if (!cs.length || cs.some(([, a]) => !isArgv(a))) return `${at}.checks: expected {"test":["npm","test"]}`
    if (p.tdd?.report && !String(p.tdd.report).startsWith('/tmp/cadre/')) return `${at}.tdd.report: must be under /tmp/cadre/`
    if (p.fetches && p.fetches.some((f: string) => !(f in p.checks))) return `${at}.fetches: must name checks`
  }
  return ps.map(p => ({ ...p, setup: p.setup ?? [] }))
}

// Depth <= 2 entries written under $HOME, parents dropped when a child is listed, build/target dirs never proposed.
export const caches = (found: string): string[] => {
  const all = found.split('\n').map(l => l.trim().replace(/^\.\//, '')).filter(Boolean).filter(l => !l.split('/').some(s => /^(target|build|dist)$/.test(s)))
  return [...new Set(all)].filter(p => !all.some(q => q !== p && q.startsWith(p + '/'))).sort()
}

const sh = (h: Host, argv: string[], cwd?: string) => h.run(argv, { cwd, timeoutMs: 600000 })

// One throwaway worktree at HEAD: setup (home-jail when auditing, writable jail with confirmed binds when validating), then every check offline (G.checkRun).
// Jail modes (G.jailMode): overlay = $HOME overlay + tmp-overlay; copy (bwrap w/o overlay, A19) = HOME=<empty scratch> audit + copied tree; none = unjailed, network unenforced, no caches learned.
export async function exec(h: Host, root: string, home: string, pkg: Pkg, o: { audit: boolean; caches?: string[]; knownRed?: string[] }): Promise<Run> {
  const scratch = `${home}/.cache/cadre/init-${h.rand(4)}`   // never under /tmp: the jail binds scratch AT /tmp and would mask wt
  const wt = `${scratch}/wt`, pkgRoot = pkg.root === '.' ? wt : `${wt}/${pkg.root}`, sh0 = `${scratch}/home`
  const out: Run = { setupOk: false, caches: [], results: {} }
  const mode = await G.jailMode(h.run), writable = (o.caches ?? []).map(c => `${home}/${c}`), J = (argv: string[]) => ({ wt, scratch, pkgRoot, argv, writable })
  const setup = (): Promise<{ exitCode: number }> => {
    if (!pkg.setup.length) return Promise.resolve({ exitCode: 0 })   // no setup step
    if (mode === 'none') return sh(h, pkg.setup, pkgRoot)
    const j = J(pkg.setup)
    return sh(h, !o.audit ? G.writableJail(j) : mode === 'overlay' ? G.homeJail({ ...j, home }) : G.homeScratchJail({ ...j, scratchHome: sh0 }))
  }
  try {
    await sh(h, ['mkdir', '-p', `${scratch}/home-up`, `${scratch}/home-work`, `${scratch}/cadre`, sh0])
    const add = await sh(h, ['git', 'worktree', 'add', '--detach', wt, 'HEAD'], root); if (add.exitCode) return out
    out.setupOk = (await setup()).exitCode === 0
    if (o.audit && mode !== 'none' && out.setupOk) out.caches = caches((await sh(h, ['find', '.', '-mindepth', '1', '-maxdepth', '2', '-type', 'd'], mode === 'overlay' ? `${scratch}/home-up` : sh0)).stdout)
    if (out.setupOk) for (const [n, argv] of Object.entries(pkg.checks)) {
      if (o.knownRed?.includes(n)) { out.results[n] = 'knownRed'; continue }
      const r = (await G.checkRun(h.run, mode, J(argv))).exitCode === 0
      out.results[n] = r ? 'pass' : pkg.fetches?.includes(n) ? 'net' : 'red'
    }
