// Epic view (UI-DESIGN 5.5, 6.2-6.4): DAG canvas (depth columns, typed edge grid, nodes with pipeline strip + flash, rail), detail strip, 6-row log, stacked list.
import type { CadreEvent, Plan, SnapTask } from '../types'
